-- =====================================================================================
-- CTRP LONG-RUN ADD-ON, piece 2019: half-years ending 31 Mar 2019 and 30 Sep 2019.
-- Candidate parameters from the NTC and eHub lists (sensitive goods, depth of exemption,
-- origin and goods record, top-ups by regime). One row per taxpayer per half-year.
-- Run as ONE statement, download as CSV, save as data/long_run_addon/addon_2019.csv
-- GENERATED by: python main.py sql --addon   (src/ctrp/addon.py explains every column)
-- =====================================================================================
WITH -- What: item rows in the window, cleaned (rules R1 to R13), each item numbered once.
-- Why:  the view repeats some items many times, so duplicates must go before any count.
raw AS (
  -- only the 24 columns the model uses, so Spark moves far less data in every step
  SELECT v.instance_id, v.key_itm_nbr, v.assessment_dt_wid, v.taxpayer_tin,
         v.regime_cd, v.decl_status, v.cpc_cd, v.extended_proc_cd,
         v.hsc_cd, v.gds_org_cty, v.customs_value, v.net_weight,
         v.supplementary_qnty, v.tax_assessed, v.original_tax_amt, v.final_amt,
         v.top_up_flg, v.amendment_flg, v.clearance_station_cd, v.is_red_flg,
         v.is_yellow_flg, v.pay_status, v.consignee_tin, v.preferential_treatment_flag,
         v.entry_num, v.dec_ref_yer,
         ROW_NUMBER() OVER (PARTITION BY v.instance_id, v.key_itm_nbr ORDER BY v.assessment_dt_wid) AS rn,
         -- R14 entry key = entry number + station + year (e.g. C12345UGKLA2026). One entry can sit under
         --     more than one declaration ID, and only its latest declaration ID (the highest) is kept.
         MAX(lpad(v.instance_id, 20, '0')) OVER (PARTITION BY COALESCE(concat(v.entry_num, v.clearance_station_cd,
             v.dec_ref_yer), v.instance_id))                                              AS latest_instance,
         -- R15 motor vehicles: a declaration with any motor vehicle item is left out (separate MV model)
         MAX(CASE WHEN substr(v.hsc_cd, 1, 4) IN ('8701', '8702', '8703', '8704', '8705', '8706', '8707', '8708', '8711') THEN 1 ELSE 0 END)
             OVER (PARTITION BY v.instance_id)                                            AS has_vehicle
  FROM dm_modeled_ura_datascience.vw_cstm_AEO_model v
  WHERE v.assessment_dt_wid >  '20180930'
    AND v.assessment_dt_wid <= '20190930'
    AND v.regime_cd IN ('IM4', 'IM7')
    AND v.decl_status <> 'Cancelled'
    AND v.taxpayer_tin RLIKE '^[0-9]{10}$'
    AND COALESCE(v.cpc_cd, '') <> '483'   -- destroyed or abandoned declarations and dummy
                                          -- reconciliation entries (CPC memo), not trade
),

-- What: one row per declaration item (duplicates dropped).
items AS (
  SELECT r.*, to_date(r.assessment_dt_wid, 'yyyyMMdd') AS adate
  FROM raw r
  WHERE r.rn = 1
    AND lpad(r.instance_id, 20, '0') = r.latest_instance   -- R14 latest declaration ID per entry
    AND r.has_vehicle = 0                                   -- R15 no motor vehicle declarations
),

-- ---------- one row per declaration ---------------------------------------------------
-- What: one row per declaration with its tax, top-up and lane.
-- Why:  tax amounts repeat on every item row, so they are taken once per declaration.
decl_all AS (
  SELECT instance_id,
         MAX(taxpayer_tin)                                   AS tin,
         MAX(adate)                                          AS adate,
         MAX(assessment_dt_wid)                              AS dt,
         MAX(regime_cd)                                      AS regime,
         COALESCE(MAX(original_tax_amt), MAX(final_amt))     AS orig_tax,
         MAX(final_amt)                                      AS final_tax,
         MAX(top_up_flg)                                     AS top_up_flg,
         MAX(amendment_flg)                                  AS amended,
         MAX(clearance_station_cd)                           AS station,
         MAX(is_red_flg)                                     AS red,
         MAX(is_yellow_flg)                                  AS yellow,
         MAX(pay_status)                                     AS pay_status,
         MAX(TRIM(consignee_tin))                            AS cons_tin,
         SUM(customs_value)                                  AS value,
         COUNT(*)                                            AS n_items
  FROM items
  GROUP BY instance_id
),

decl AS (
  SELECT d.*,
         CASE WHEN d.top_up_flg = 'Y' AND d.final_tax > d.orig_tax THEN 1 ELSE 0 END             AS topped_up,
         CASE WHEN d.top_up_flg = 'Y' AND d.final_tax > d.orig_tax
              THEN d.final_tax - d.orig_tax ELSE 0 END                                          AS top_up,
         CASE WHEN d.final_tax < d.orig_tax THEN 1 ELSE 0 END                                   AS negative_top_up
  FROM decl_all d
),

-- ---------- items with their declaration's lane and outcome (this piece's year only) -----
half_items AS (
  SELECT i.instance_id, i.taxpayer_tin AS tin, i.cpc_cd, substr(i.hsc_cd, 1, 8) AS hs8,
         substr(i.hsc_cd, 1, 2) AS ch, COALESCE(i.gds_org_cty, '??') AS org,
         i.customs_value AS value, i.tax_assessed AS tax,
         CASE WHEN CAST(substr(i.assessment_dt_wid, 5, 2) AS INT) BETWEEN 4 AND 9 THEN CAST(substr(i.assessment_dt_wid, 1, 4) AS INT) * 2 + 1 WHEN CAST(substr(i.assessment_dt_wid, 5, 2) AS INT) >= 10 THEN (CAST(substr(i.assessment_dt_wid, 1, 4) AS INT) + 1) * 2 ELSE CAST(substr(i.assessment_dt_wid, 1, 4) AS INT) * 2 END AS h,
         CASE WHEN d.red = 1 OR d.yellow = 1 THEN 1 ELSE 0 END                         AS chk,
         CASE WHEN (d.red = 1 OR d.yellow = 1) AND d.topped_up = 1 THEN 1 ELSE 0 END   AS hit,
         CASE WHEN substr(i.hsc_cd, 1, 8) IN ('04011000', '04012000', '04014000', '04015000', '04021000', '04022100', '04022900', '04029100', '04029900', '04032000', '04039000', '04061000', '04062000', '04063000', '04064000', '04069000', '10059000', '10061000', '10062000', '10063000', '10064000', '11010000', '11022000', '11029010', '17011210', '17011290', '17011310', '17011390', '17011410', '17011490', '17019100', '17019910', '17019920', '17019990', '52085110', '52085210', '52095110', '52105110', '52115110', '52121510', '52122510', '55134110', '55144110', '62114210', '62114310', '62114910', '63022100', '63023100', '63025100', '63029100') THEN 1 ELSE 0 END          AS sens,
         CASE WHEN COALESCE(i.gds_org_cty, '') IN ('EG', 'GB', 'AE', 'KP', 'IN', 'AF', 'AM', 'AZ', 'BH', 'BD', 'BT', 'BN', 'KH', 'CN', 'CY', 'GE', 'HK', 'ID', 'IR', 'IQ', 'IL', 'JP', 'JO', 'KZ', 'KW', 'KG', 'LA', 'LB', 'MO', 'MY', 'MV', 'MN', 'MM', 'NP', 'OM', 'PK', 'PS', 'PH', 'QA', 'SA', 'SG', 'KR', 'LK', 'SY', 'TW', 'TJ', 'TH', 'TL', 'TR', 'TM', 'UZ', 'VN', 'YE') THEN 10
              WHEN COALESCE(i.gds_org_cty, '') IN ('KE', 'TZ', 'RW', 'BI', 'SS', 'CD', 'SO', 'UG', 'KM', 'DJ', 'ER', 'SZ', 'ET', 'LY', 'MG', 'MW', 'MU', 'SC', 'SD', 'TN', 'ZM', 'ZW', 'AO', 'BW', 'LS', 'MZ', 'NA', 'ZA') THEN 5 ELSE 0 END          AS ntc_org
  FROM items i
  JOIN decl d ON i.instance_id = d.instance_id
  WHERE i.customs_value > 0
),

-- normal tax rate per tariff line: tax over value of items with no exemption (APC 000)
hs_rate AS (
  SELECT hs8, SUM(tax) / SUM(value) AS normal_rate
  FROM half_items
  WHERE cpc_cd = '000' AND tax >= 0
  GROUP BY hs8
  HAVING COUNT(*) >= 20
),

-- origin x HS chapter record in the same half-year, OTHER taxpayers only (the taxpayer's own
-- checks are taken out, so its own top-ups never feed this measure)
own AS (
  SELECT tin, org, ch, h, SUM(chk) AS own_checked, SUM(hit) AS own_hits, SUM(value) AS v
  FROM half_items GROUP BY tin, org, ch, h
),
og AS (
  SELECT org, ch, h, SUM(chk) AS checked, SUM(hit) AS hits FROM half_items GROUP BY org, ch, h
),
gl AS (
  SELECT h, SUM(hit) / SUM(chk) AS g_rate FROM half_items GROUP BY h
),
orig AS (
  SELECT o.tin, o.h,
         SUM(o.v * (g.hits - o.own_hits + 30 * l.g_rate)
                 / (g.checked - o.own_checked + 30))                           AS value_x_origin_rate,
         SUM(o.v)                                                                      AS value_with_origin_rate
  FROM own o
  JOIN og g ON o.org = g.org AND o.ch = g.ch AND o.h = g.h
  JOIN gl l ON o.h = l.h
  GROUP BY o.tin, o.h
),

itm AS (
  SELECT x.tin, x.h,
         SUM(x.value)                                                                    AS item_value_ugx,
         SUM(CASE WHEN x.sens = 1 THEN x.value ELSE 0 END)                               AS sensitive_value_ugx,
         COUNT(DISTINCT CASE WHEN x.sens = 1 THEN x.instance_id END)                      AS sensitive_entries,
         SUM(CASE WHEN x.cpc_cd <> '000' THEN x.value ELSE 0 END)                        AS exempt_apc_value_ugx,
         SUM(CASE WHEN x.cpc_cd <> '000' AND x.tax <= 0.005 * x.value THEN x.value ELSE 0 END) AS full_exempt_value_ugx,
         SUM(CASE WHEN x.cpc_cd <> '000' AND x.tax >  0.005 * x.value THEN x.value ELSE 0 END) AS partial_exempt_value_ugx,
         SUM(CASE WHEN x.cpc_cd <> '000' AND r.normal_rate IS NOT NULL
                  THEN GREATEST(r.normal_rate * x.value - x.tax, 0) ELSE 0 END)          AS tax_relief_ugx,
         SUM(CASE WHEN r.normal_rate IS NOT NULL THEN r.normal_rate * x.value ELSE 0 END) AS normal_tax_ugx,
         SUM(CASE WHEN x.ntc_org = 10 THEN x.value ELSE 0 END)                           AS ntc_origin10_value_ugx,
         SUM(CASE WHEN x.ntc_org = 5 THEN x.value ELSE 0 END)                            AS ntc_origin5_value_ugx
  FROM half_items x
  LEFT JOIN hs_rate r ON x.hs8 = r.hs8
  GROUP BY x.tin, x.h
),

-- ---------- top-ups by regime, per declaration -------------------------------------------
reg AS (
  SELECT tin, CASE WHEN CAST(substr(dt, 5, 2) AS INT) BETWEEN 4 AND 9 THEN CAST(substr(dt, 1, 4) AS INT) * 2 + 1 WHEN CAST(substr(dt, 5, 2) AS INT) >= 10 THEN (CAST(substr(dt, 1, 4) AS INT) + 1) * 2 ELSE CAST(substr(dt, 1, 4) AS INT) * 2 END AS h,
         SUM(CASE WHEN regime = 'IM4' THEN orig_tax ELSE 0 END)                                AS im4_original_tax_ugx,
         SUM(CASE WHEN regime = 'IM4' THEN top_up ELSE 0 END)                                  AS im4_top_up_ugx,
         SUM(CASE WHEN regime = 'IM4' AND (red = 1 OR yellow = 1) THEN 1 ELSE 0 END)            AS im4_checked,
         SUM(CASE WHEN regime = 'IM4' AND (red = 1 OR yellow = 1) AND topped_up = 1 THEN 1 ELSE 0 END) AS im4_hits,
         SUM(CASE WHEN regime = 'IM7' THEN orig_tax ELSE 0 END)                                AS im7_original_tax_ugx,
         SUM(CASE WHEN regime = 'IM7' THEN top_up ELSE 0 END)                                  AS im7_top_up_ugx,
         SUM(CASE WHEN regime = 'IM7' AND (red = 1 OR yellow = 1) THEN 1 ELSE 0 END)            AS im7_checked,
         SUM(CASE WHEN regime = 'IM7' AND (red = 1 OR yellow = 1) AND topped_up = 1 THEN 1 ELSE 0 END) AS im7_hits
  FROM decl
  GROUP BY tin, CASE WHEN CAST(substr(dt, 5, 2) AS INT) BETWEEN 4 AND 9 THEN CAST(substr(dt, 1, 4) AS INT) * 2 + 1 WHEN CAST(substr(dt, 5, 2) AS INT) >= 10 THEN (CAST(substr(dt, 1, 4) AS INT) + 1) * 2 ELSE CAST(substr(dt, 1, 4) AS INT) * 2 END
)

SELECT r.tin AS taxpayer_tin,
       CASE WHEN r.h % 2 = 1 THEN concat(CAST(CAST((r.h - 1) / 2 AS INT) AS STRING), '-09-30')
            ELSE concat(CAST(CAST(r.h / 2 AS INT) AS STRING), '-03-31') END AS period_end,
       r.im4_original_tax_ugx, r.im4_top_up_ugx, r.im4_checked, r.im4_hits,
       r.im7_original_tax_ugx, r.im7_top_up_ugx, r.im7_checked, r.im7_hits,
       m.item_value_ugx, m.sensitive_value_ugx, m.sensitive_entries,
       m.exempt_apc_value_ugx, m.full_exempt_value_ugx, m.partial_exempt_value_ugx,
       m.tax_relief_ugx, m.normal_tax_ugx, o.value_x_origin_rate, o.value_with_origin_rate,
       m.ntc_origin10_value_ugx, m.ntc_origin5_value_ugx
FROM reg r
LEFT JOIN itm m  ON r.tin = m.tin AND r.h = m.h
LEFT JOIN orig o ON r.tin = o.tin AND r.h = o.h
